{
  "url": "https://your-app.example.com/webhook-received",
  "webhooks": [
    {
      "events": [
        "jira:issue_created",
        "jira:issue_updated"
      ],
      "fieldIdsFilter": [
        "summary",
        "customfield_10029"
      ],
      "jqlFilter": "project = PROJ"
    },
    {
      "events": [
        "jira:issue_deleted"
      ],
      "jqlFilter": "project IN (PROJ, EXP) AND status = done"
    },
    {
      "events": [
        "issue_property_set"
      ],
      "issuePropertyKeysFilter": [
        "my-issue-property-key"
      ],
      "jqlFilter": "project = PROJ"
    }
  ]
}

